76: function xpForNextLevel(level) { return 100 + (level - 1) * 25 }
77: function levelInfo(total = game.xp) {
78:   let level = 1, remaining = Math.max(0, Math.floor(total))
79:   while (remaining >= xpForNextLevel(level)) { remaining -= xpForNextLevel(level); level++ }
80:   return { level, current: remaining, needed: xpForNextLevel(level), percent: Math.min(100, remaining / xpForNextLevel(level) * 100) }
81: }
82: function awardXP(amount, reason, claimKey = null) {
83:   if (claimKey && game.xpClaims.includes(claimKey)) return false
84:   const reward = Math.max(0, Math.floor(Number(amount) || 0))
85:   if (!reward) return false
86:   if (claimKey) game.xpClaims.push(claimKey)
87:   game.xp += reward
88:   return true
89: }
