/* Discovery: graphic adaptation picker */
.discover-bar{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:10px 0 6px;padding:10px 12px;border:1px solid #344235;border-radius:7px;background:#151f18;font:8px var(--mono);letter-spacing:.6px}
.discover-bar>span{color:#cbd5c8}
.discover-cost{color:var(--lime);font-weight:700}
.discover-reward{color:#a8bd83}
.discover-pick{color:#ff8a7a;font-weight:700}
.adapt-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:8px;margin:6px 0 4px}
.adapt-card{display:grid;grid-template-columns:44px 1fr 34px;align-items:center;gap:8px;padding:10px;border:1px solid #29362e;border-radius:7px;background:#151f18;cursor:pointer;transition:border-color .15s,box-shadow .15s,background .15s}
.adapt-card:hover{border-color:#536447;box-shadow:0 0 0 1px #536447}
.adapt-card.selected{border-color:var(--lime);box-shadow:0 0 14px var(--lime)22;background:#1a281b}
.adapt-card input{appearance:none;margin:0;width:0;height:0;opacity:0;pointer-events:none}
.adapt-face{position:relative;width:40px;height:40px;border:1px solid #3b493d;border-radius:10px;background:#0e1612;display:grid;place-items:center;overflow:hidden}
.adapt-ring{position:absolute;inset:-2px;border:2px solid transparent;border-radius:12px;opacity:0;transition:opacity .15s,border-color .15s}
.adapt-card.selected .adapt-ring{opacity:1;border-color:var(--lime);box-shadow:0 0 10px var(--lime)66}
.adapt-glyph{font-size:19px;line-height:1;filter:drop-shadow(0 1px 1px #0004)}
.adapt-copy{display:flex;flex-direction:column;gap:2px;min-width:0}
.adapt-copy>b{font-size:10px;color:#e5eddf;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.adapt-copy>small{font-size:7px;color:#8f9e8d;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.adapt-copy>em{font-size:6px;font-style:normal;color:#6b7a6d;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;line-height:1.3}
.adapt-part{font:7px var(--mono);letter-spacing:.4px;color:#a6c970;text-align:right;white-space:nowrap}
.adapt-mark{display:none;place-items:center;width:26px;height:26px;border-radius:8px;background:var(--lime);color:#0b1411;font-weight:800;font-size:12px}
.adapt-card.selected .adapt-mark{display:grid}
.discover-hint{margin:8px 0 2px;color:#829086;font-size:8px;line-height:1.5}
@media(max-width:650px){.adapt-grid{grid-template-columns:1fr 1fr}.adapt-card{padding:8px}.adapt-copy>b{font-size:9px}}
